import Foundation

enum PickState: String { case used, dropped, added, rejected, unassociated }

final class Pick {
    unowned let station: Station
    let sample: Int
    let duration: Int
    let ratio: Double
    let amplitude: Int
    let clipped: Bool
    var time: Double { Double(sample) / 100 }
    var state = PickState.unassociated
    var event: Int?
    var residual: Double?
    var firstResidual: Double?
    var assigned = false
    init(_ station: Station, _ sample: Int, _ duration: Int, _ ratio: Double, _ amplitude: Int, _ clipped: Bool) {
        self.station = station; self.sample = sample; self.duration = duration; self.ratio = ratio; self.amplitude = amplitude; self.clipped = clipped
    }
}

func floorDivide(_ numerator: Int, _ denominator: Int) -> Int { numerator / denominator - (numerator % denominator < 0 ? 1 : 0) }

func detectStation(_ station: Station, _ params: Parameters) -> [Pick] {
    let samples = station.samples, length = samples.count
    let mean = floorDivide(samples.reduce(0, +), length), detrended = samples.map { $0 - mean }
    let energy = detrended.map { $0 * $0 }, sw = params.staWindow, lw = params.ltaWindow
    var prefix = [0]
    for value in energy { prefix.append(prefix.last! + value) }
    var picks: [Pick] = [], triggers = 0, shortTriggers = 0, on = false, beginning = 0, peakRatio = 0.0
    func finish(_ end: Int) {
        triggers += 1
        let duration = end - beginning
        if duration < params.minDuration { shortTriggers += 1; return }
        var position = beginning
        while position - 1 >= beginning - sw + 1 && energy[position - 1] >= params.noiseLevel { position -= 1 }
        let last = min(position + params.amplitudeWindow, length)
        let amplitude = (position..<last).map { abs(detrended[$0]) }.max()!
        let clipped = (position..<last).contains { abs(samples[$0]) >= params.clipLevel }
        picks.append(Pick(station, station.start + position, duration, peakRatio, amplitude, clipped))
    }
    for i in (sw + lw - 1)..<length {
        let sta = prefix[i + 1] - prefix[i - sw + 1], lta = prefix[i - sw + 1] - prefix[i - sw - lw + 1]
        if !on {
            if sta * lw * params.triggerOn[1] >= params.triggerOn[0] * lta * sw {
                on = true; beginning = i; peakRatio = Double(sta * lw) / Double(lta * sw)
            }
        } else if sta * lw * params.triggerOff[1] < params.triggerOff[0] * lta * sw { finish(i); on = false }
        else { peakRatio = max(peakRatio, Double(sta * lw) / Double(lta * sw)) }
    }
    if on { finish(length) }
    station.mean = mean
    station.noise = median(detrended.map { Double(abs($0)) })
    station.peak = detrended.map { abs($0) }.max()!
    station.clippedSamples = samples.filter { abs($0) >= params.clipLevel }.count
    station.triggers = triggers; station.shortTriggers = shortTriggers; station.picks = picks
    return picks
}

import Foundation

final class Station {
    let code: String
    let x: Int
    let y: Int
    let elevation: Int
    let order: Int
    let start: Int
    let samples: [Int]
    var mean = 0
    var noise = 0.0
    var peak = 0
    var clippedSamples = 0
    var triggers = 0
    var shortTriggers = 0
    var picks: [Pick] = []
    var timeCorrection = 0.0
    init(_ code: String, _ x: Int, _ y: Int, _ elevation: Int, _ order: Int, _ start: Int, _ samples: [Int]) {
        self.code = code; self.x = x; self.y = y; self.elevation = elevation; self.order = order; self.start = start; self.samples = samples
    }
}

struct GridRange {
    let low: Int
    let high: Int
    let step: Int
    var values: [Int] { Array(stride(from: low, through: high, by: step)) }
    init(_ values: [Int]) { low = values[0]; high = values[1]; step = values[2] }
}

struct Parameters {
    let staWindow: Int
    let ltaWindow: Int
    let triggerOn: [Int]
    let triggerOff: [Int]
    let minDuration: Int
    let noiseLevel: Int
    let amplitudeWindow: Int
    let clipLevel: Int
    let associationWindow: Int
    let minStations: Int
    let velocity: Double
    let gridX: GridRange
    let gridY: GridRange
    let gridZ: GridRange
    let residualLimit: Double
    let qualityA: [Double]
    let qualityB: [Double]
    let cluster: [Double]
    let localMagnitude: [Double]
    let durationMagnitude: [Double]
    let mapArea: [Int]
    let mapSize: [Int]
    let section: [Int]
    let timeline: [Int]
}

func readLines(_ path: String) throws -> [String] { try String(contentsOfFile: path, encoding: .ascii).split(separator: "\n").map(String.init) }

func loadInputs() throws -> (stations: [Station], params: Parameters) {
    let geometries = try readLines("input/stations.csv").dropFirst().map { $0.components(separatedBy: ",") }
    let lines = try readLines("input/waveforms.txt")
    var cursor = 0, stations: [Station] = []
    for (index, geometry) in geometries.enumerated() {
        let header = lines[cursor].components(separatedBy: " ")
        let count = Int(header[3])!
        cursor += 1
        var samples: [Int] = []
        while samples.count < count { samples += lines[cursor].components(separatedBy: " ").map { Int($0)! }; cursor += 1 }
        stations.append(Station(geometry[0], Int(geometry[1])!, Int(geometry[2])!, Int(geometry[3])!, index, Int(header[2])!, samples))
    }
    let settings = Dictionary(uniqueKeysWithValues: try readLines("input/params.txt").map { line in
        let fields = line.components(separatedBy: " ")
        return (fields[0], Array(fields.dropFirst()))
    })
    func ints(_ key: String) -> [Int] { settings[key]!.map { Int($0)! } }
    func reals(_ key: String) -> [Double] { settings[key]!.map { Double($0)! } }
    func integer(_ key: String) -> Int { Int(settings[key]![0])! }
    let params = Parameters(staWindow: integer("sta_window"), ltaWindow: integer("lta_window"), triggerOn: ints("trigger_on"), triggerOff: ints("trigger_off"),
                            minDuration: integer("min_duration"), noiseLevel: integer("noise_level"), amplitudeWindow: integer("amplitude_window"), clipLevel: integer("clip_level"),
                            associationWindow: integer("association_window"), minStations: integer("min_stations"), velocity: reals("velocity")[0],
                            gridX: GridRange(ints("grid_x")), gridY: GridRange(ints("grid_y")), gridZ: GridRange(ints("grid_z")), residualLimit: reals("residual_limit")[0],
                            qualityA: reals("quality_a"), qualityB: reals("quality_b"), cluster: reals("cluster"), localMagnitude: reals("local_magnitude"),
                            durationMagnitude: reals("duration_magnitude"), mapArea: ints("map_area"), mapSize: ints("map_size"), section: ints("section"), timeline: ints("timeline"))
    return (stations, params)
}
